def maxRemovable(s, p, removable):
    inf = len(removable)
    when = [inf] * len(s)
    for idx, pos in enumerate(removable):
        when[pos] = idx

    def ok(k):
        j = 0
        for i, c in enumerate(s):
            if j < len(p) and when[i] >= k and c == p[j]:
                j += 1
        return j == len(p)

    lo, hi = 0, len(removable)
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if ok(mid):
            lo = mid
        else:
            hi = mid - 1
    return lo
